    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~GPIO_AFRH_AFSEL8_Msk) | (6U << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->MODER  = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk)   | (2U << GPIO_MODER_MODE8_Pos);
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos); /* Very high speed */

    /* 3. Configure TIM1 timebase
     * TIM1 kernel clock is 170 MHz (APB2 prescaler = 1).
     * PSC = 0 -> timer counter clock = 170 MHz / (0 + 1) = 170 MHz.
     * ARR = 8499 -> PWM frequency = 170 MHz / (8499 + 1) = 20,000 Hz (20 kHz, 0% error).
     * CCR1 = 2125 -> Duty cycle = 2125 / (8499 + 1) = 25.0% (0% error).
     */
    TIM1->PSC  = 0;
    TIM1->ARR  = 8499;
    TIM1->CCR1 = 2125;

    /* 4. Configure Channel 1 for PWM mode 1 with preload enabled */
    /* OC1M = 0110b (PWM mode 1: active while CNT < CCR1), OC1PE = 1 (preload) */
