    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);
    GPIOA->AFR[1] &= ~(0xFU << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos);
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);
    GPIOA->OTYPER &= ~GPIO_OTYPER_OT8;
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;

    /* 3. Configure TIM1 timing for 20 kHz PWM, 25% duty cycle */
    /* TIM1 clock = 170 MHz. Frequency = TIM1_CLK / ((PSC + 1) * (ARR + 1)) */
    /* 170 MHz / ((0 + 1) * (8499 + 1)) = 20,000 Hz */
    /* Duty cycle = CCR1 / (ARR + 1) = 2125 / 8500 = 25.0% */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    /* Configure Channel 1 in PWM mode 1 (OC1M = 0110) with preload enabled (OC1PE = 1) */
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM1->CCMR1 |= (TIM_CCMR1_OC1M_1 | TIM_CCMR1_OC1M_2 | TIM_CCMR1_OC1PE);

    /* Output polarity active high (CC1P = 0) and enable output on CH1 (CC1E = 1) */
    TIM1->CCER &= ~(TIM_CCER_CC1P | TIM_CCER_CC1NP);
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable Auto-reload preload (ARPE) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Enable Main Output (MOE) in BDTR (required for advanced timer TIM1) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Generate an update event to load preloaded registers into shadow registers */
    TIM1->EGR = TIM_EGR_UG;

    /* Enable counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    while (1) {
    }
