    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL0_Msk;
    GPIOA->AFR[0] |= (1U << GPIO_AFRL_AFSEL0_Pos);

    /* Cấu hình tốc độ đầu ra của chân PA0 ở mức Very High */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED0_Pos);

    /* 3. Cấu hình TIM2 tạo PWM 1 kHz, duty cycle 50 % */
    /* Xung nhịp TIM2 kernel clock = 170 MHz (PCLK1 = 170 MHz, prescaler = 1) */
    /* Với PSC = 0: tần số đếm = 170 MHz */
    /* ARR = 170 000 000 / (1 * 1000) - 1 = 169999 */
    /* CCR1 = 170000 * 50% = 85000 */
    TIM2->PSC = 0U;
    TIM2->ARR = 169999U;
    TIM2->CCR1 = 85000U;

    /* Cấu hình Channel 1 sang PWM mode 1 (OC1M = 0110b) và bật preload (OC1PE = 1) */
    TIM2->CCMR1 &= ~(TIM_CCMR1_CC1S_Msk | TIM_CCMR1_OC1M_Msk);
    TIM2->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Cấu hình cực tính tích cực mức cao (CC1P = 0) và kích hoạt đầu ra Channel 1 (CC1E = 1) */
    TIM2->CCER &= ~TIM_CCER_CC1P;
    TIM2->CCER |= TIM_CCER_CC1E;

    /* Bật tính năng auto-reload preload trên thanh ghi CR1 */
    TIM2->CR1 |= TIM_CR1_ARPE;

    /* Phát sinh sự kiện update (UG) để nạp trước các giá trị vào shadow registers */
    TIM2->EGR = TIM_EGR_UG;

    /* Bật bộ đếm TIM2 */
    TIM2->CR1 |= TIM_CR1_CEN;

    /* Vòng lặp vô tận */
    while (1) {
    }
