#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable peripheral clocks for GPIOA and USART2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* 2. Configure PA2 (TX) and PA3 (RX) to alternate function mode (MODER[1:0] = 0b10) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE2_Msk | GPIO_MODER_MODE3_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE2_Pos) | (2U << GPIO_MODER_MODE3_Pos);

    /* 3. Assign PA2 and PA3 to Alternate Function 7 (USART2_TX and USART2_RX) */
    GPIOA->AFR[0] &= ~((0xFU << GPIO_AFRL_AFSEL2_Pos) | (0xFU << GPIO_AFRL_AFSEL3_Pos));
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL2_Pos) | (7U << GPIO_AFRL_AFSEL3_Pos);

    /*
     * 4. Configure Baud Rate:
     * Clock source: PCLK1 = 16 MHz (reset default USART2SEL = 00 in RCC_CCIPR).
     * Oversampling by 16: OVER8 = 0 in USART_CR1 (reset default).
     *
     * BRR = f_CK / Baud = 16,000,000 / 9600 = 1666.666...
     * Rounded to nearest integer: BRR = 1667 (0x0683).
     * Actual baud rate = 16,000,000 / 1667 = 9598.08 baud.
     * Error = (9598.08 - 9600) / 9600 = -0.02% (well within +-2%).
     * Note: As required, BRR is written before enabling the USART.
     */
    USART2->BRR = 1667U;

    /*
     * 5. Frame format defaults (already 0 out of reset in USART_CR1 and USART_CR2):
     * - Word length: 8 data bits (M[1:0] = 00 in USART_CR1)
     * - Parity control disabled: PCE = 0 in USART_CR1
     * - Stop bits: 1 stop bit (STOP[1:0] = 00 in USART_CR2)
     * - Oversampling by 16: OVER8 = 0 in USART_CR1
     *
     * 6. Enable Transmitter (TE), Receiver (RE), and USART peripheral (UE)
     */
    USART2->CR1 |= USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    while (1)
    {
    }
}
```

### Explanation

1. **Clock Configuration**:
   - `RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN` enables the clock for GPIO port A [STM32G474_RM0440 p.306].
   - `RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN` enables the clock for USART2 on the APB1 peripheral bus [STM32G474_RM0440 p.309].
   - By default out of reset, `RCC->CCIPR` selects PCLK1 as the clock source for USART2 (`USART2SEL = 0b00`) [STM32G474_RM0440 p.322]. Since the chip is in its reset state, PCLK1 = 16 MHz.

2. **GPIO Pin Multiplexing**:
   - PA2 and PA3 are set to Alternate Function mode (`MODER = 0b10`) [STM32G474_RM0440 p.355].
   - PA2 and PA3 are assigned to Alternate Function 7 (AF7), which maps PA2 to `USART2_TX` and PA3 to `USART2_RX` [STM32G474_Datasheet p.73]. Because pins 2 and 3 belong to the low nibble of port A, bits are modified in `AFR[0]` (`GPIOx_AFRL`) [STM32G474_RM0440 p.359].

3. **Baud Rate Calculation**:
   - In 16x oversampling mode (`OVER8 = 0`), the formula for baud rate generation is:
     $$\text{USARTDIV} = \frac{f_{CK}}{\text{Baud}} = \frac{16\,000\,000}{9600} \approx 1666.67$$
   - Rounding to the nearest integer yields `BRR = 1667` (`0x0683`) [STM32G474_RM0440 p.1708, p.1755].
   - The resulting baud rate is $16\,000\,000 / 1667 \approx 9598.08$ baud, which has an error of approximately $-0.02\%$, comfortably within the $\pm 2\%$ tolerance requirement.
   - `USART2->BRR` is configured prior to setting `UE` in `USART2->CR1`.

4. **Frame Format and Peripheral Activation**:
   - Reset values of `USART2->CR1` and `USART2->CR2` naturally configure 1 stop bit (`STOP[1:0] = 00`), 8 data bits (`M[1:0] = 00`), no parity (`PCE = 0`), and 16x oversampling (`OVER8 = 0`) [STM32G474_RM0440 p.1740, p.1747].
   - Setting `TE` (Transmitter Enable), `RE` (Receiver Enable), and `UE` (USART Enable) simultaneously activates the transceiver [STM32G474_RM0440 p.1740].

