#include "stm32g4xx.h"

int main(void) {
    /* 1. Enable peripheral clocks for GPIOC (AHB2) and TIM1 (APB2) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PC0 pin:
     * - Alternate function mode: MODER0 = 0b10
     * - Alternate function selection: AF2 (TIM1_CH1) in AFRL (AFR[0])
     * - High speed output
     */
    GPIOC->MODER &= ~GPIO_MODER_MODE0_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE0_Pos);

    GPIOC->AFR[0] &= ~GPIO_AFRL_AFSEL0_Msk;
    GPIOC->AFR[0] |= (2U << GPIO_AFRL_AFSEL0_Pos);

    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED0_Pos);

    /* 3. Configure TIM1 time-base:
     * Input clock: TIM1CLK = 170 MHz (APB2 prescaler = 1).
     * Target frequency: 20 kHz.
     * f_PWM = TIM1CLK / ((PSC + 1) * (ARR + 1))
     * With PSC = 0: ARR = (170,000,000 / 20,000) - 1 = 8499.
     * Target duty cycle: 25 %
     * CCR1 = (ARR + 1) * 0.25 = 8500 * 0.25 = 2125.
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    /* 4. Configure Channel 1:
     * - PWM mode 1 (OC1M = 0110b): active while CNT < CCR1, inactive otherwise
     * - Output compare preload enable (OC1PE = 1)
