    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (0x6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Auto-reload preload enable */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Enable Channel 1 output (active-high polarity by default: CC1P = 0) */
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Generate update event to load preloaded registers (PSC, ARR, CCR1) */
    TIM1->EGR = TIM_EGR_UG;

    /* 5. Enable Main Output for advanced-control timer (MOE bit in BDTR) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 6. Start counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    while (1) {
        /* Main loop */
    }
