#include "stm32g4xx.h"

int main(void)
{
    /* 1. Enable peripheral clocks for GPIOA and USART2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* 2. Configure PA2 (TX) and PA3 (RX) for Alternate Function 7 (USART2) */
    /* Set MODER for PA2 and PA3 to 10 (Alternate function mode) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE2_Msk | GPIO_MODER_MODE3_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE2_Pos) | (2U << GPIO_MODER_MODE3_Pos);

    /* Set AF7 in AFRL for PA2 (bits 11:8) and PA3 (bits 15:12) */
    GPIOA->AFR[0] &= ~((0xFU << GPIO_AFRL_AFSEL2_Pos) | (0xFU << GPIO_AFRL_AFSEL3_Pos));
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL2_Pos) | (7U << GPIO_AFRL_AFSEL3_Pos);

    /* 3. Configure baud rate:
     * Clock source: PCLK1 = 16 MHz (reset default, RCC_CCIPR USART2SEL = 00b)
     * Oversampling by 16 (OVER8 = 0 in USART_CR1, reset default)
     * USARTDIV = 16,000,000 / 9600 = 1666.6667
     * Nearest integer in USART_BRR: 1667 (0x0683)
     * Resulting baud rate: 16,000,000 / 1667 = 9598.08 baud (-0.02% error, within ±2%)
     */
    USART2->BRR = 1667U;

    /* 4. Configure frame format and enable USART:
     * 8 data bits: M1=0, M0=0 (reset default in CR1)
     * Parity control disabled: PCE=0 (reset default in CR1)
     * 1 stop bit: STOP[1:0]=00b (reset default in CR2)
     * Enable Transmitter (TE), Receiver (RE), and USART peripheral (UE)
     * (Written after setting BRR as required)
     */
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    while (1)
    {
    }
}
```

