int main(void)
{
    /* 1. Bật clock cho ngoại vi PWR và chuyển sang Range 1 Boost mode để chạy > 150 MHz */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    (void)RCC->APB1ENR1; /* Đọc lại để đảm bảo clock PWR đã được kích hoạt */

    /* Xóa bit R1MODE (bit 8 = 0) để chọn Range 1 Boost mode (cho phép SYSCLK lên đến 170 MHz) */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 2. Cấu hình độ trễ Flash (Flash latency):
     * Ở Range 1 Boost mode với HCLK = 168 MHz (136 < HCLK <= 170 MHz),
     * cần 4 chu kỳ chờ (4 wait states / 5 CPU cycles).
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS)
    {
        /* Chờ cho đến khi cấu hình Flash Latency có hiệu lực */
    }

    /* 3. Bật bộ dao động HSE và chờ tín hiệu sẵn sàng */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY))
    {
        /* Chờ cờ HSERDY = 1 */
    }

    /* 4. Cấu hình PLL:
     * - Nguồn đầu vào: HSE (8 MHz)
     * - PLLM = 2 (giá trị nạp vào trường PLLM là 1, vì PLLM = value + 1):
     *   f_VCO_IN = 8 MHz / 2 = 4 MHz (nằm trong dải hợp lệ 2.66 MHz đến 16 MHz)
     * - PLLN = 84:
     *   f_VCO_OUT = 4 MHz * 84 = 336 MHz (nằm trong dải hợp lệ Range 1: 96 MHz đến 344 MHz)
     * - PLLR = 2 (giá trị nạp là 00b vì PLLR = (value + 1) * 2):
