### Mã nguồn C (`main.c`)

```c
#include "stm32g4xx.h"

int main(void)
{
    /* 1. Bật clock cho giao diện Power Control (PWR) để ghi vào các thanh ghi của PWR */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Cấu hình Range 1 Boost Mode:
     * Theo tài liệu, khi SYSCLK > 150 MHz (lên đến tối đa 170 MHz), cần chọn Range 1 Boost Mode
     * bằng cách xóa bit R1MODE trong thanh ghi PWR_CR5.
     */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Cấu hình Flash read access latency:
     * Tại VCORE Range 1 Boost Mode và HCLK = 168 MHz (136 MHz < HCLK <= 170 MHz),
     * cần 4 chu kỳ chờ (4 Wait States, tức 5 CPU cycles).
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY_Msk) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_4WS) {
        /* Chờ cho đến khi độ trễ bộ nhớ Flash được cập nhật */
    }

    /* 4. Bật dao động thạch anh ngoài HSE (8 MHz) */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Chờ cho đến khi HSE ổn định và sẵn sàng */
    }

    /* 5. Cấu hình bộ nhân tần Main PLL:
     * Nguồn clock vào PLL: HSE = 8 MHz (PLLSRC = 3, RCC_PLLCFGR_PLLSRC_HSE).
     * Bộ chia đầu vào M: M = 1 (giá trị ghi 0 -> chia 1) => fVCO_IN = 8 MHz / 1 = 8 MHz (nằm trong dải 2.66 - 16 MHz).
     * Hệ số nhân VCO N: N = 42 (giá trị ghi 42) => fVCO_OUT = 8 MHz * 42 = 336 MHz (nằm trong dải 96 - 344 MHz).
     * Bộ chia đầu ra PLL "R": R = 2 (giá trị ghi 0 -> chia 2) => fPLL_R = 336 MHz / 2 = 168 MHz (sai số 0.0 %).
     * Bật đầu ra PLL "R" bằng bit PLLREN.
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (0 << RCC_PLLCFGR_PLLM_Pos) |
                   (42 << RCC_PLLCFGR_PLLN_Pos) |
                   (0 << RCC_PLLCFGR_PLLR_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* 6. Bật Main PLL */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Chờ cho đến khi PLL khóa pha (lock) và sẵn sàng */
    }

    /* 7. Quy trình chuyển đổi xung nhịp an toàn khi tần số HCLK > 80 MHz:
     * Cấu hình bộ chia AHB (HPRE) chia 2 trước khi chuyển sang PLL.
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV2;

    /* 8. Chuyển nguồn xung nhịp hệ thống (SYSCLK) sang PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW_Msk) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL) {
        /* Chờ đến khi PLL chính thức được chọn làm SYSCLK */
    }

    /* Chờ ít nhất 1 us ở trạng thái trung gian trước khi chuyển bộ chia AHB về 1 */
    for (volatile int i = 0; i < 200; i++) {
        __NOP();
    }

