int main(void)
{
    /* 1. Bật clock cho giao diện Power Control (PWR) để ghi vào các thanh ghi của PWR */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Cấu hình Range 1 Boost Mode:
     * Theo tài liệu, khi SYSCLK > 150 MHz (lên đến tối đa 170 MHz), cần chọn Range 1 Boost Mode
     * bằng cách xóa bit R1MODE trong thanh ghi PWR_CR5.
     */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Cấu hình Flash read access latency:
     * Tại VCORE Range 1 Boost Mode và HCLK = 168 MHz (136 MHz < HCLK <= 170 MHz),
     * cần 4 chu kỳ chờ (4 Wait States, tức 5 CPU cycles).
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY_Msk) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_4WS) {
        /* Chờ cho đến khi độ trễ bộ nhớ Flash được cập nhật */
    }

    /* 4. Bật dao động thạch anh ngoài HSE (8 MHz) */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Chờ cho đến khi HSE ổn định và sẵn sàng */
