    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL) {
        /* Chờ đến khi PLL chính thức được chọn làm SYSCLK */
    }

    /* Chờ ít nhất 1 us ở trạng thái trung gian trước khi chuyển bộ chia AHB về 1 */
    for (volatile int i = 0; i < 200; i++) {
