     * - PLLM = 1 (giá trị ghi 0) -> fVCO_IN = 8 MHz / 1 = 8 MHz (nằm trong dải 2.66 - 16 MHz)
     * - PLLN = 42 -> fVCO = 8 MHz * 42 = 336 MHz (nằm trong dải 96 - 344 MHz)
     * - PLLR = 2 (giá trị ghi 0) -> fPLL_R = 336 MHz / 2 = 168 MHz
     * - PLLREN = 1 (bật đầu ra PLLCLK cho hệ thống)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (0U << RCC_PLLCFGR_PLLM_Pos) |
                   (42U << RCC_PLLCFGR_PLLN_Pos) |
                   (0U << RCC_PLLCFGR_PLLR_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* 6. Bật PLL và chờ PLL khóa ổn định (PLLRDY = 1) */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY))
    {
    }

    /* 7. Quy trình chuyển đổi xung nhịp lên > 80 MHz / 150 MHz:
     * Tạm thời chia đôi xung nhịp AHB (HPRE = DIV2) trước khi chuyển sang PLL
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV2;

    /* 8. Chuyển nguồn xung nhịp hệ thống (SYSCLK) sang PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW_Msk) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL)
    {
    }

    /* Đợi tối thiểu 1 µs theo quy định của RM0440 trước khi chuyển AHB prescaler về 1 */
    for (volatile int i = 0; i < 200; i++)
    {
    }

    /* 9. Đặt lại AHB prescaler = 1 (HPRE = DIV1) để đạt SYSCLK = HCLK = 168 MHz */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV1;

    /* Đảm bảo hệ số chia APB1 và APB2 là 1 (PPRE1 = 0, PPRE2 = 0) -> PCLK1 = PCLK2 = 168 MHz */
    RCC->CFGR &= ~(RCC_CFGR_PPRE1_Msk | RCC_CFGR_PPRE2_Msk);

    /* Vòng lặp chính */
    while (1)
    {
    }
}
```

### Giải thích chi tiết:

1. **Chế độ điện áp Range 1 Boost Mode**:
   - STM32G474 ở chế độ Range 1 Normal chỉ hỗ trợ tần số SYSCLK lên đến 150 MHz [STM32G474_Datasheet p.123]. Để hoạt động ở mức 168 MHz (tối đa 170 MHz), vi điều khiển phải được kích hoạt **Range 1 Boost Mode** bằng cách xóa bit `R1MODE` trong thanh ghi `PWR_CR5` [STM32G474_RM0440 p.232-233, p.267].
   - Để truy cập thanh ghi `PWR_CR5`, clock giao tiếp PWR được bật thông qua bit `PWREN` trong thanh ghi `RCC_APB1ENR1` [STM32G474_RM0440 p.309].

2. **Flash Latency**:
   - Theo Bảng 9 (Table 9) của RM0440, đối với VCORE Range 1 Boost Mode và tần số HCLK trong khoảng 136 MHz < HCLK ≤ 170 MHz, số chu kỳ chờ Flash (Flash wait states - `LATENCY`) bắt buộc phải đặt là **4 WS (5 CPU cycles)** [STM32G474_RM0440 p.98].
   - Việc ghi bit `LATENCY` vào `FLASH_ACR` được xác nhận lại bằng vòng lặp busy-wait để đảm bảo thời gian truy cập Flash có hiệu lực trước khi nâng xung nhịp hệ thống [STM32G474_RM0440 p.98, p.130].

3. **Cấu hình PLL và tần số**:
   - Nguồn vào PLL: thạch anh ngoài HSE = 8 MHz [STM32G474_Datasheet p.117].
   - Hệ số chia đầu vào: $M = 1$ (bit `PLLM[3:0] = 0`), suy ra $f_{\text{VCO\_IN}} = 8 \text{ MHz} / 1 = 8 \text{ MHz}$ (thỏa mãn dải cho phép $2.66 \text{ MHz} \le f_{\text{VCO\_IN}} \le 16 \text{ MHz}$) [STM32G474_Datasheet p.123].
   - Hệ số nhân: $N = 42$ (bit `PLLN[6:0] = 42`), suy ra $f_{\text{VCO}} = 8 \text{ MHz} \times 42 = 336 \text{ MHz}$ (thỏa mãn dải cho phép $96 \text{ MHz} \le f_{\text{VCO}} \le 344 \text{ MHz}$) [STM32G474_Datasheet p.123].
   - Hệ số chia đầu ra: $R = 2$ (bit `PLLR[1:0] = 0`), suy ra $f_{\text{PLL\_R}} = 336 \text{ MHz} / 2 = 168.000000 \text{ MHz}$ (sai số 0.000 %, hoàn toàn nằm trong dung sai yêu cầu 0.1 %) [STM32G474_Datasheet p.123].

4. **Trình tự chuyển đổi xung nhịp an toàn**:
   - Theo quy định kỹ thuật trong mục 7.2.7 và Bảng 38 của RM0440 khi nâng tần số hệ thống lên trên 80 MHz / 150 MHz, xung nhịp AHB tạm thời được chia đôi (`HPRE = DIV2`), sau đó chuyển xung nhịp hệ thống sang PLL (`SW = PLL`), chờ cờ trạng thái `SWS` xác nhận đã chuyển thành công, chờ tối thiểu 1 µs rồi mới khôi phục `HPRE` về `DIV1` để đạt trọn vẹn 168 MHz [STM32G474_RM0440 p.233, p.279].
   - Các prescaler APB1 (`PPRE1`) và APB2 (`PPRE2`) được giữ nguyên ở mức chia 1 (`DIV1`) [STM32G474_RM0440 p.290], cho kết quả $SYSCLK = HCLK = PCLK1 = PCLK2 = 168 \text{ MHz}$.

